*{margin:0;padding:0;box-sizing:border-box}
body{background:#0f172a;color:#e2e8f0;font-family:'Segoe UI',Tahoma,sans-serif;display:flex;justify-content:center;padding:8px;min-height:100vh}
.container{max-width:680px;width:100%}
h1{text-align:center;font-size:14px;color:#fbbf24;margin-bottom:4px}
canvas{background:#0f172a;border:1px solid #334155;border-radius:8px;display:block;margin:0 auto;width:100%;max-width:660px;height:380px}
.controls{display:flex;flex-direction:column;gap:4px;margin-top:6px;background:#1e293b;border-radius:6px;padding:8px;border:1px solid #334155}
.ctrl-row{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
