.ctrl-row.actions{gap:4px;justify-content:center}
.ctrl-group{flex:1;min-width:100px;display:flex;flex-direction:column;gap:1px}
.ctrl-group label{font-size:9px;color:#94a3b8;white-space:nowrap}
.ctrl-group .val{color:#fbbf24;font-size:12px;font-weight:700}
.ctrl-group.wide{flex:2;min-width:180px}
.ctrl-group.hidden{display:none}
.btn{background:#334155;color:#94a3b8;border:1px solid #475569;border-radius:4px;padding:4px 8px;font-size:10px;cursor:pointer;text-align:center;transition:all .15s;white-space:nowrap}
.btn.active{background:#3b82f6;color:#fff;border-color:#3b82f6;font-weight:700}
.btn:hover{background:#475569;color:#e2e8f0}
.btn.play{background:#166534;color:#86efac;border-color:#22c55e}
.btn.play.active{background:#5f1a1a;color:#fca5a5;border-color:#ef4444}
.btn.danger{background:#5f1a1a;color:#fca5a5;border-color:#7f1d1d}
input[type=range]{width:100%;height:4px;-webkit-appearance:none;appearance:none;background:#334155;border-radius:2px;outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:#f59e0b;cursor:pointer}
.stats{display:flex;gap:6px;justify-content:center;margin-top:4px;font-size:11px;color:#94a3b8;flex-wrap:wrap}
.stats span{background:#1e293b;padding:3px 8px;border-radius:4px;border:1px solid #334155;text-align:center}
.stats .big{font-size:13px;font-weight:700}
.stats .pH{color:#38bdf8}
.stats .V{color:#f59e0b}
.stats .eq{color:#22c55e}
.stats .region{color:#c084fc;font-size:10px}
.ctrl-group .hint{font-size:8px;color:#64748b}

