const c = document.getElementById('c'), ctx = c.getContext('2d');
const W = 660, H = 380, padL = 55, padR = 20, padT = 25, padB = 45;
const gw = W - padL - padR, gh = H - padT - padB;

var mode = 'sa', Ca = 0.1, Cb = 0.1, Va = 20, Vb = 0, pKa = 4.76, pKb = 4.76;
var playing = false, speed = 1, autoTimer = null;
var cachedCurve = [], paramsChanged = true;

function getVe() { return Ca * Va / Cb; }
function getMaxV() { return Math.max(40, 2 * getVe() + 5); }
const Kw = 1e-14;

function recomputeCurveIfNeeded() {
  if (!paramsChanged) return;
  var maxV = getMaxV(), step = 0.1;
  cachedCurve = [];
  for (var v = 0; v <= maxV + step; v += step)
    cachedCurve.push({ v: v, ph: calcPH(v, mode, Ca, Cb, Va, pKa, pKb) });
  paramsChanged = false;
}

function calcPH(v, m, ca, cb, va, pka, pkb) {
  const Vt = va + v;
  if (Vt <= 0) return 7;
  const Ve = ca * va / cb;
  if (Ve <= 0) return 7;

  if (m === 'sa') {
    if (v < Ve - 1e-12) {
      const H = (ca * va - cb * v) / Vt;
      return H > 0 ? -Math.log10(H) : 7;
    } else if (v > Ve + 1e-12) {
      const OH = (cb * v - ca * va) / Vt;
      return OH > 0 ? 14 + Math.log10(OH) : 7;
    } else return 7;
  }

  if (m === 'wa') {
    const Ka = Math.pow(10, -pka);
    if (v < Ve - 1e-12) {
      if (v <= 0) {
        const H = Math.sqrt(Ka * ca);
        return -Math.log10(H);
      }
      const HA = (ca * va - cb * v) / Vt;
      const A = (cb * v) / Vt;
      if (HA <= 0 || A <= 0) return 7;
      return pka + Math.log10(A / HA);
    } else if (v > Ve + 1e-12) {
      const OH = (cb * v - ca * va) / Vt;
      return OH > 0 ? 14 + Math.log10(OH) : 7;
    } else {
      const Cb_eq = ca * va / Vt;
      const Kb = Kw / Ka;
      const OH = Math.sqrt(Kb * Cb_eq);
      return 14 + Math.log10(OH);
    }
  }

  if (m === 'sb') {
    if (v < Ve - 1e-12) {
      const OH = (ca * va - cb * v) / Vt;
      return OH > 0 ? 14 + Math.log10(OH) : 7;
    } else if (v > Ve + 1e-12) {
      const H = (cb * v - ca * va) / Vt;
      return H > 0 ? -Math.log10(H) : 7;
    } else return 7;
  }

  if (m === 'wb') {
    const Kb = Math.pow(10, -pkb);
    const Ka_conj = Kw / Kb;
    if (v < Ve - 1e-12) {
      if (v <= 0) {
        const OH = Math.sqrt(Kb * ca);
        return 14 + Math.log10(OH);
      }
      const B = (ca * va - cb * v) / Vt;
      const BH = (cb * v) / Vt;
      if (B <= 0 || BH <= 0) return 7;
      return 14 - pkb + Math.log10(B / BH);
    } else if (v > Ve + 1e-12) {
      const H = (cb * v - ca * va) / Vt;
      return H > 0 ? -Math.log10(H) : 7;
    } else {
      const Cb_eq = ca * va / Vt;
      const H = Math.sqrt(Ka_conj * Cb_eq);
      return -Math.log10(H);
    }
  }
  return 7;
}

function getRegion(v, m, Ve) {
  if (v < 0.01) return 'البداية';
  if (Math.abs(v - Ve) < 0.05) return 'نقطة التكافؤ';
  if (v < Ve - 0.05) {
    if (m === 'wa' || m === 'wb') return 'منطقة التخزين المؤقت';
    return 'قبل نقطة التكافؤ';
  }
  return 'بعد نقطة التكافؤ';
}

function draw() {
  ctx.clearRect(0, 0, W, H);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(0, 0, W, H);

  const Ve = getVe();
  const maxV = getMaxV();
  const maxPH = 14;

  ctx.strokeStyle = '#475569';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(padL, padT);
  ctx.lineTo(padL, H - padB);
  ctx.lineTo(W - padR, H - padB);
  ctx.stroke();

  ctx.fillStyle = '#64748b';
  ctx.font = '9px "Segoe UI",Tahoma,sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  const xStep = maxV > 60 ? 10 : 5;
  for (let i = 0; i <= maxV; i += xStep) {
    const x = padL + (i / maxV) * gw;
    ctx.fillText(i, x, H - padB + 4);
    ctx.strokeStyle = 'rgba(30,41,59,0.6)';
    ctx.beginPath();
    ctx.moveTo(x, padT);
    ctx.lineTo(x, H - padB);
    ctx.stroke();
  }

  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  for (let i = 0; i <= maxPH; i += 2) {
    const y = padT + gh - (i / maxPH) * gh;
    ctx.fillText(i, padL - 6, y);
    ctx.strokeStyle = 'rgba(30,41,59,0.6)';
    ctx.beginPath();
    ctx.moveTo(padL, y);
    ctx.lineTo(W - padR, y);
    ctx.stroke();
  }

  ctx.fillStyle = '#64748b';
  ctx.font = '9px "Segoe UI",Tahoma,sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('V_b (mL)', padL + gw / 2, H - padB + 22);
  ctx.save();
  ctx.translate(12, padT + gh / 2 + 8);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('pH', 0, 0);
  ctx.restore();

  recomputeCurveIfNeeded();
  var curve = cachedCurve;

  const grad = ctx.createLinearGradient(0, padT, 0, H - padB);
  grad.addColorStop(0, 'rgba(56,189,248,0.08)');
  grad.addColorStop(0.5, 'rgba(56,189,248,0.03)');
  grad.addColorStop(1, 'rgba(56,189,248,0.01)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  curve.forEach((p, i) => {
    const x = padL + (p.v / maxV) * gw;
    const y = padT + gh - (p.ph / maxPH) * gh;
    i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  const lastX = padL + (curve[curve.length - 1].v / maxV) * gw;
  ctx.lineTo(lastX, H - padB);
  ctx.lineTo(padL, H - padB);
  ctx.closePath();
  ctx.fill();

  ctx.strokeStyle = '#38bdf8';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  curve.forEach((p, i) => {
    const x = padL + (p.v / maxV) * gw;
    const y = padT + gh - (p.ph / maxPH) * gh;
    if (p.ph >= 0 && p.ph <= 14 && isFinite(p.ph)) {
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    } else {
      if (p.ph < 0) ctx.moveTo(x, padT);
      else if (p.ph > 14) ctx.moveTo(x, H - padB);
    }
  });
  ctx.stroke();

  const eqPH = calcPH(Ve, mode, Ca, Cb, Va, pKa, pKb);
  if (Ve > 0 && Ve <= maxV && eqPH >= 0 && eqPH <= 14) {
    const ex = padL + (Ve / maxV) * gw;
    const ey = padT + gh - (eqPH / maxPH) * gh;
    ctx.strokeStyle = '#22c55e';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(ex, padT);
    ctx.lineTo(ex, H - padB);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(padL, ey);
    ctx.lineTo(W - padR, ey);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#22c55e';
    ctx.beginPath();
    ctx.arc(ex, ey, 5, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#22c55e';
    ctx.font = 'bold 9px "Segoe UI",Tahoma,sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'bottom';
    ctx.fillText('نقطة التكافؤ pH=' + eqPH.toFixed(2), W - padR, ey - 8);
  }

  if ((mode === 'wa' || mode === 'wb') && Ve > 0 && Ve <= maxV) {
    const halfVe = Ve / 2;
    if (halfVe > 0) {
      let halfPH;
      if (mode === 'wa') halfPH = pKa;
      else halfPH = 14 - pKb;
      if (halfPH >= 0 && halfPH <= 14) {
        const hx = padL + (halfVe / maxV) * gw;
        const hy = padT + gh - (halfPH / maxPH) * gh;
        ctx.fillStyle = '#f59e0b';
        ctx.beginPath();
        ctx.arc(hx, hy, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#f59e0b';
        ctx.font = '8px "Segoe UI",Tahoma,sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText('½ تكافؤ pH=' + halfPH.toFixed(2), hx, hy + 7);
      }
    }
  }

  const phNow = calcPH(Vb, mode, Ca, Cb, Va, pKa, pKb);
  const cx = padL + (Vb / maxV) * gw;
  const cy = padT + gh - (phNow / maxPH) * gh;

  ctx.strokeStyle = 'rgba(245,158,11,0.3)';
  ctx.lineWidth = 1;
  ctx.setLineDash([2, 3]);
  ctx.beginPath();
  ctx.moveTo(cx, padT);
  ctx.lineTo(cx, H - padB);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.shadowColor = 'rgba(245,158,11,0.5)';
  ctx.shadowBlur = 10;
  ctx.fillStyle = '#f59e0b';
  ctx.beginPath();
  ctx.arc(cx, cy, 7, 0, Math.PI * 2);
  ctx.fill();
  ctx.shadowBlur = 0;

  document.getElementById('phDisplay').textContent = 'pH = ' + (isFinite(phNow) ? phNow.toFixed(2) : '--');
  document.getElementById('vbDisplay').textContent = 'Vb = ' + Vb.toFixed(1) + ' mL';

  const Veff = Ve || 0;
  document.getElementById('eqDisplay').textContent = 'Veq = ' + Veff.toFixed(1) + ' mL, pHeq = ' + (isFinite(eqPH) ? eqPH.toFixed(2) : '--');

  const region = getRegion(Vb, mode, Veff);
  document.getElementById('regionDisplay').textContent = region;
}

function updateSliderMax() {
  const maxV = getMaxV();
  const vbSlider = document.getElementById('vbSlider');
  vbSlider.max = maxV;
  if (Vb > maxV) { Vb = maxV; vbSlider.value = maxV; }
}

function updatePkaPkbVisibility() {
  document.getElementById('pkaGroup').classList.toggle('hidden', mode !== 'wa');
  document.getElementById('pkbGroup').classList.toggle('hidden', mode !== 'wb');
}

function readParams() {
  paramsChanged = true;
  Ca = parseFloat(document.getElementById('caSlider').value);
  Cb = parseFloat(document.getElementById('cbSlider').value);
  Va = parseFloat(document.getElementById('vaSlider').value);
  pKa = parseFloat(document.getElementById('pkaSlider').value);
  pKb = parseFloat(document.getElementById('pkbSlider').value);
  document.getElementById('caLabel').textContent = Ca.toFixed(2);
  document.getElementById('cbLabel').textContent = Cb.toFixed(2);
  document.getElementById('vaLabel').textContent = Va.toFixed(1);
  document.getElementById('pkaLabel').textContent = pKa.toFixed(2);
  document.getElementById('pkbLabel').textContent = pKb.toFixed(2);
  updateSliderMax();
  draw();
}

function resetSim() {
  paramsChanged = true;
  playing = false;
  if (autoTimer) { clearInterval(autoTimer); autoTimer = null; }
  document.getElementById('btnAuto').textContent = '▶ تشغيل تلقائي';
  document.getElementById('btnAuto').classList.remove('active');
  Vb = 0;
  document.getElementById('vbSlider').value = 0;
  document.getElementById('vbLabel').textContent = '0.0 mL';
  readParams();
}

function toggleAuto() {
  playing = !playing;
  const btn = document.getElementById('btnAuto');
  if (playing) {
    btn.textContent = '⏸ إيقاف';
    btn.classList.add('active');
    if (autoTimer) clearInterval(autoTimer);
    const delay = speed === 2 ? 30 : speed === 1 ? 80 : 200;
    autoTimer = setInterval(() => {
      if (!playing) return;
      const maxV = getMaxV();
      Vb = parseFloat(document.getElementById('vbSlider').value);
      Vb += 0.1 * speed;
      if (Vb > maxV) { Vb = maxV; toggleAuto(); return; }
      document.getElementById('vbSlider').value = Vb;
      document.getElementById('vbLabel').textContent = Vb.toFixed(1) + ' mL';
      draw();
    }, delay);
  } else {
    btn.textContent = '▶ تشغيل تلقائي';
    btn.classList.remove('active');
    if (autoTimer) { clearInterval(autoTimer); autoTimer = null; }
  }
}

document.getElementById('caSlider').addEventListener('input', function () {
  document.getElementById('caLabel').textContent = parseFloat(this.value).toFixed(2);
  readParams();
});
document.getElementById('cbSlider').addEventListener('input', function () {
  document.getElementById('cbLabel').textContent = parseFloat(this.value).toFixed(2);
  readParams();
});
document.getElementById('vaSlider').addEventListener('input', function () {
  document.getElementById('vaLabel').textContent = parseFloat(this.value).toFixed(1);
  readParams();
});
document.getElementById('pkaSlider').addEventListener('input', function () {
  document.getElementById('pkaLabel').textContent = parseFloat(this.value).toFixed(2);
  readParams();
});
document.getElementById('pkbSlider').addEventListener('input', function () {
  document.getElementById('pkbLabel').textContent = parseFloat(this.value).toFixed(2);
  readParams();
});
document.getElementById('vbSlider').addEventListener('input', function () {
  Vb = parseFloat(this.value);
  document.getElementById('vbLabel').textContent = Vb.toFixed(1) + ' mL';
  draw();
});

document.querySelectorAll('[data-mode]').forEach(b => {
  b.addEventListener('click', function () {
    if (playing) toggleAuto();
    document.querySelectorAll('[data-mode]').forEach(x => x.classList.remove('active'));
    this.classList.add('active');
    mode = this.dataset.mode;
    paramsChanged = true;
    updatePkaPkbVisibility();
    readParams();
  });
});

document.getElementById('btnAuto').addEventListener('click', toggleAuto);
document.getElementById('btnReset').addEventListener('click', resetSim);
document.getElementById('btnSpeed').addEventListener('click', function () {
  speed = speed === 2 ? 1 : speed === 1 ? 0.5 : 2;
  this.textContent = 'سرعة: ' + (speed === 2 ? 'سريعة' : speed === 1 ? 'عادية' : 'بطيئة');
  if (playing) { toggleAuto(); toggleAuto(); }
});

updatePkaPkbVisibility();
readParams();
